ee:message.ee:set-payload:
%dw 2.0
output application/json
var errorPayload = error.cause.errorMessage.payload default {}
var errorMsg = if (errorPayload is String) 
                  (if (errorPayload contains "cellphone" or errorPayload contains "Cellphone" or errorPayload contains "celular")
                      "Número de celular inválido. Debe ser un número colombiano de 10 dígitos."
                   else if (errorPayload contains "document" or errorPayload contains "Document")
                      "Número de documento inválido."
                   else errorPayload)
               else (errorPayload.message default error.description default "Error de validación en los datos enviados")
---
{
	"status": 400,
	"code": "VALIDATION_ERROR",
	"message": {
		"message": errorMsg
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "lisim-sapi-services",
			"message": error.errorType.identifier default "HTTP:BAD_REQUEST"
		}
	]
}

%dw 2.0
output application/json
---
{
	"status": 503,
	"code": "SERVICE_UNAVAILABLE",
	"message": {
		"message": "El servicio de validación de identidad no está disponible en este momento. Por favor intente más tarde."
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "lisim-sapi-services",
			"message": error.errorType.identifier default "CONNECTIVITY_ERROR"
		}
	]
}

%dw 2.0
output application/json
---
{
	"status": 401,
	"code": "AUTHENTICATION_ERROR",
	"message": {
		"message": "Error de autenticación con el servicio de validación de identidad."
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "lisim-sapi-services",
			"message": error.errorType.identifier default "AUTHENTICATION_ERROR"
		}
	]
}

%dw 2.0
output application/json
var statusCode = error.cause.errorMessage.attributes.statusCode default 500
var errorMsg = if (statusCode == 404) 
                  "Recurso no encontrado en el servicio de validación."
               else if (statusCode == 429)
                  "Se ha excedido el límite de consultas. Por favor intente más tarde."
               else 
                  (error.cause.errorMessage.payload.message default error.description default "Error en el servicio de validación de identidad")
---
{
	"status": statusCode,
	"code": if (statusCode == 404) "NOT_FOUND" 
	        else if (statusCode == 429) "TOO_MANY_REQUESTS"
	        else "LISIM_ERROR",
	"message": {
		"message": errorMsg
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "lisim-sapi-services",
			"message": error.errorType.identifier default "LISIM_ERROR"
		}
	]
}
